package com.jamshed.hrms.controller; import com.jamshed.hrms.dto.CandidateRequest;import com.jamshed.hrms.entity.Candidate;import com.jamshed.hrms.exception.ResourceNotFoundException;import com.jamshed.hrms.repository.CandidateRepository;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/candidates") public class RecruitmentController{private final CandidateRepository r;public RecruitmentController(CandidateRepository r){this.r=r;}@GetMapping public List<Candidate> all(){return r.findAll();}@PostMapping public Candidate create(@Valid @RequestBody CandidateRequest d){return r.save(Candidate.builder().name(d.name()).email(d.email()).phone(d.phone()).position(d.position()).stage(d.stage()==null?"APPLIED":d.stage()).experienceYears(d.experienceYears()).source(d.source()).build());}@PatchMapping("/{id}/stage") public Candidate stage(@PathVariable Long id,@RequestParam String value){Candidate c=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Candidate not found"));if(!List.of("APPLIED","SCREENING","INTERVIEW","OFFER","HIRED","REJECTED").contains(value))throw new com.jamshed.hrms.exception.BusinessException("Invalid recruitment stage");c.setStage(value);return r.save(c);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);}}
